import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"DeepSeekV4，继续开源","description":"传闻中的DeepSeek V4模型终于来了，性能比肩顶级闭源模型。关键是，开源！开源！造福一方！API费用低，被媒体亲切的欢呼“迈入百万上下文普惠时代”。","frontmatter":{"title":"DeepSeekV4，继续开源","sidebarTitle":"DeepSeek V4 开源","description":"传闻中的DeepSeek V4模型终于来了，性能比肩顶级闭源模型。关键是，开源！开源！造福一方！API费用低，被媒体亲切的欢呼“迈入百万上下文普惠时代”。","date":"2026-04-25T00:00:00.000Z","category":"AI世界","tags":["AI技术"],"order":3},"headers":[],"relativePath":"articles/ai/ai-tech/deepseekV4.md","filePath":"articles/ai/ai-tech/deepseekV4.md","articleMeta":{"updated":"2026-04-25","words":2582,"minutes":6}}`),a={name:`articles/ai/ai-tech/deepseekV4.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><img src="https://static.wyclab.com/20260424233837491260424.webp" alt=""></p><p>传闻中的DeepSeek V4模型终于来了。</p><p>从2025年1月，DeepSeek-R1惊艳全国、闪亮登场以来，各路AI就像各路诸侯一样，快速迭代，参数越来越强大，你方唱罢我登场，每个十天半个月，就有宣称“史上最强”的模型推出。更何况还有AI Agent、龙虾Open Claw等各类概念满天飞。博主作为一个普通人，甚至对这些AI不断登顶的新闻都麻木了。</p><p>而这次DeepSeek-V4被各路媒体争先恐后的报道，我个人认为是人民心中的地位比较高、群众知晓度比较高。根据官方的宣传文档，V4 PRO版本的性能比肩顶级闭源模型 。所谓的顶级闭源模型，自然是指美国AI三幻神：Claude 、GPT 、Gemini，分别对应美资企业<strong>Anthropic</strong> 公司、 <strong>OpenAI</strong> 公司、<strong>Google</strong>（谷歌）公司，他们用着最先进的英伟达芯片训练自己的模型，但无一例外都选择了<strong>“闭源”</strong>。（哪怕名字里带有Open，哈哈）</p><p>而国内的AI生态，在Deepseek的带领下，不仅竞争格局更加百花齐放，并且Kimi、阿里千问、智谱等均选择开源自己的头部模型。开源意味着政府、企业可以本地化部署，满足自托管的保密要求。也意味着中小企业、甚至个人，获得了站在巨人的肩膀上的机会，百家争鸣，争相攀登技术高峰。</p><p>更值得一提的是，<strong>DeepSeek V4</strong> 延续了其“价格屠夫”的定位，API费用是头部模型的几十分之一。博主通过Gemini Pro整理如下：</p><table tabindex="0"><thead><tr><th><strong>模型开发商</strong></th><th><strong>旗舰模型名称</strong></th><th><strong>输入价格 (1M Tokens)</strong></th><th><strong>输出价格 (1M Tokens)</strong></th><th><strong>成本分析与优势</strong></th></tr></thead><tbody><tr><td><strong>DeepSeek</strong></td><td><strong>DeepSeek V4 Pro</strong></td><td><strong>$1.74</strong></td><td><strong>$3.48</strong></td><td><strong>断层级性价比</strong>。价格仅为 OpenAI/Anthropic 顶尖模型的 1/3 到 1/8。</td></tr><tr><td><strong>OpenAI</strong></td><td>GPT-5.5</td><td>$5.00</td><td>$30.00</td><td>行业标杆，但输出价格极其昂贵，适合作为高阶 Agent 的“大脑”。</td></tr><tr><td><strong>OpenAI</strong></td><td>GPT-5.4 Standard</td><td>$2.50</td><td>$15.00</td><td>目前广泛使用的 GPT 主力模型，各项能力均衡。</td></tr><tr><td><strong>Anthropic</strong></td><td>Claude Opus 4.7</td><td>$5.00</td><td>$25.00</td><td>擅长复杂代理任务与极具深度的分析，定价处于最昂贵的梯队。</td></tr><tr><td><strong>Anthropic</strong></td><td>Claude Sonnet 4.6</td><td>$3.00</td><td>$15.00</td><td>编程与指令遵循表现极佳。</td></tr><tr><td><strong>Google</strong></td><td>Gemini 3.1 Pro</td><td>$2.00</td><td>$12.00</td><td>200K 上下文内价格较低（长文本超过 200K 后价格翻倍至 $4.00/$18.00）。</td></tr><tr><td><strong>阿里 (Qwen)</strong></td><td>通义千问 Max</td><td>~$0.30 - $2.80</td><td>~$0.80 - $8.00</td><td>具有极强的本土语言优势和价格政策，国内大量调用常有阶梯折扣。</td></tr></tbody></table><p>想让AI变得聪明、理解你，就需要更长的记忆和上下文，而更长的上下文意味着更昂贵的Token费用（按字节计算），Deepseek支持1M超长上下文，被媒体亲切的称为“迈入百万上下文普惠时代”。</p><p>在2026年3月，斯坦福做了一个《The 2026 AI Index Report》（翻译为：2026年AI指数报告），其中有两个图我放一下：</p><p><img src="https://static.wyclab.com/image-20260424231214529260424.webp" alt="image-20260424231214529"></p><p>第一个图是中美模型的对比，横轴是时间，从2023年5月至2026年1月，蓝色是美国，紫色是中国。评分标准是Arena（<strong>Arena评分是一种通过“盲测对战+人类投票”来给大模型排名的评估体系</strong>， 是目前大模型领域最权威的“民间排行榜”）。我个人认为这个曲线图是有价值且真实的，可以看到中美差距最近的点就是2025年1月DeepSeek-R1深度思考模型诞生的时候，之后阿里千问、字节的模型更强，但是较同期的美国模型，差距在变大。</p><p><img src="https://static.wyclab.com/image-20260424231721518260424.webp" alt="image-20260424231721518"></p><p>第二个图是闭源模型和开源模型的对比，和上图一样，横轴是时间，蓝色是闭源，紫色是开源。数据截止到2026年1月。和上图的中美对比基本一致。差异在于后面比较强的字节模型没有开源。我个人认为这个曲线图也是有价值的，在我个人对豆包、千问、Gemini等模型使用中，美国的闭源模型就是更胜一筹。</p><p>上述图表截至日期为2026年1月，博主大胆预测以下，美国闭源模型即使有英伟达最先进芯片的加持，但是在DeepSeek的开源+价格屠夫的引领下，就好像人民战争的汪洋大海，中国的AI模型将具备咬住第一梯队的能力，甚至在3-5年内实现对美国的赶超。</p><p>最后，Deepseek的公告中，有一段“写在后面的话”，博主摘录原文如下：</p><blockquote><p>「不诱于誉，不恐于诽，率道而行，端然正己。」</p><p>感谢每一位用户的信任与支持，大家的肯定、建议和期许，是我们不竭探索、持续进步的动力，也让我们始终坚守初心，专注于不懈的创新。</p><p>我们将始终秉持长期主义的原则理念，在尝试与思考中踏实前行，努力向实现 AGI 的目标不断靠近。</p></blockquote><p>一家“被”登上神坛的企业，没有着急上市自证，更没有昙花一现、泯然众人，而是根据自己的原则和对技术的坚持，践行了真正的<code>OPEN</code>理念，有这样的企业引领，AI才能造福社会而非祸乱。</p><p><img src="https://static.wyclab.com/kanenori-mountain-6320288_1920260424.webp" alt="kanenori-mountain-6320288_1920"></p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};